import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import './BaseAppStyle.css';

import { Snek } from 'apps/web/src/components/base-org/root/Redesign/Section/BaseApp/tokenSVG/Snek';
import { Clawster } from 'apps/web/src/components/base-org/root/Redesign/Section/BaseApp/tokenSVG/Clawster';
import { Virtual } from 'apps/web/src/components/base-org/root/Redesign/Section/BaseApp/tokenSVG/Virtual';

const TOKEN_INTERVAL_SECONDS = 3; // change N here

type Token = {
  id: number;
  component: React.ReactNode;
};

const TOKENS: Token[] = [
  {
    id: 1,
    component: <Snek />,
  },
  {
    id: 2,
    component: <Clawster />,
  },
  {
    id: 3,
    component: <Virtual />,
  },
  {
    id: 4,
    component: <Clawster />,
  },
  {
    id: 5,
    component: <Clawster />,
  },
];

export function BaseAppTrade() {
  const [currentIndex, setCurrentIndex] = useState(0); // index of the front token in TOKENS
  const [isHovering, setIsHovering] = useState(false);

  useEffect(() => {
    const intervalId = setInterval(() => {
      if (isHovering) return;
      setCurrentIndex((prev) => (prev + 1) % TOKENS.length);
    }, TOKEN_INTERVAL_SECONDS * 1000);

    return () => clearInterval(intervalId);
  }, [isHovering]);

  function advanceTokens() {
    setCurrentIndex((prev) => (prev + 1) % TOKENS.length);
  }

  const VISIBLE_COUNT = 3;
  const total = TOKENS.length;
  const visibleTokens: Token[] = [];

  for (let i = 0; i < Math.min(VISIBLE_COUNT, total); i++) {
    const tokenIndex = (currentIndex - i + total) % total;
    visibleTokens.push(TOKENS[tokenIndex]);
  }

  return (
    <div
      onClick={advanceTokens}
      className="base-app-trade"
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => setIsHovering(false)}
    >
      {visibleTokens.map((token, index) => {
        const offset = -index * 12; // vertical gap between stacked cards
        const opacity = Math.max(0, 1 - index * 0.3);
        const scale = 1 - index * 0.08;
        const isFirst = index === 0;

        return (
          <div key={token.id} className="card-wrapper">
            <motion.div
              className="card"
              initial={
                isFirst ? { y: offset + 40, opacity: 0, scale: 0.9 } : { y: offset, opacity, scale }
              }
              animate={{ y: offset, opacity, scale }}
              transition={{ type: 'spring', bounce: 0.3, duration: 0.6 }}
              style={{
                zIndex: 100 - index,
              }}
            >
              {token.component}
            </motion.div>
          </div>
        );
      })}
    </div>
  );
}

